22.10.17.6.2 Class template function_ref [func.wrap.ref.class]
🔗
namespace std {
  template<class R, class... ArgTypes>
  class function_ref<R(ArgTypes...) cv noexcept(noex)> {
  public:
    // [func.wrap.ref.ctor], constructors and assignment operators
    template<class F> function_ref(F*) noexcept;
    template<class F> constexpr function_ref(F&&) noexcept;
    template<auto c, class F> constexpr function_ref(constant_wrapper<c, F>) noexcept;
    template<auto c, class F, class U>
      constexpr function_ref(constant_wrapper<c, F>, U&&) noexcept;
    template<auto c, class F, class T>
      constexpr function_ref(constant_wrapper<c, F>, cv T*) noexcept;
    constexpr function_ref(const function_ref&) noexcept = default;
    constexpr function_ref& operator=(const function_ref&) noexcept = default;
    template<class T> function_ref& operator=(T) = delete;
    // [func.wrap.ref.inv], invocation
    R operator()(ArgTypes...) const noexcept(noex);
  private:
    template<class... T>
      static constexpr bool is-invocable-using = see below;             // exposition only
    R (*thunk-ptr)(BoundEntityType, ArgTypes&&...) noexcept(noex);      // exposition only
    BoundEntityType bound-entity;                                       // exposition only
  };
  // [func.wrap.ref.deduct], deduction guides
  template<class F>
    function_ref(F*) -> function_ref<F>;
  template<auto c, class F0>
    function_ref(constant_wrapper<c, F0>) -> function_ref<see below>;
  template<auto c, class F, class T>
    function_ref(constant_wrapper<c, F>, T&&) -> function_ref<see below>;
}
1
#
An object of class
function_ref<R(Args...) cv noexcept(noex)>
stores a pointer to function thunk-ptr and
an object bound-entity.
 The object bound-entity has
an unspecified trivially copyable type BoundEntityType, that
models copyable and
is capable of storing a pointer to object value or a pointer to function value.
 The type of thunk-ptr is
R(*)(BoundEntityType, Args&&...) noexcept(noex).
2
#
Each specialization of function_ref is
a trivially copyable type ([basic.types.general])
that models copyable.
3
#
Within subclause [func.wrap.ref],
call-args is an argument pack with elements such that
decltype((call-args))...
denote ArgTypes&&... respectively.

